contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public payable {
        require(v <= address(c).balance);
        uint balanceBefore = address(c).balance;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        c.withdraw(v); if (__ESBMC_reverted()) return;
        assert(address(c).balance == balanceBefore - v && c.depositsCount() == depositsBefore);
    }

    receive() external payable {}
}

